static int inSmall(int v, int *small, int smallSize) {
  for (int i = 0; i < smallSize; i++) {
    if (small[i] == v) return i;
  }
  return -1;
}

int *shortestSeq(int *big, int bigSize, int *small, int smallSize, int *returnSize) {
  int bestLen = bigSize + 1, bestL = -1, bestR = -1;
  for (int l = 0; l < bigSize; l++) {
    if (inSmall(big[l], small, smallSize) < 0) continue;
    int *seen = (int *)calloc(smallSize, sizeof(int));
    int found = 0, r = l;
    for (; r < bigSize; r++) {
      int idx = inSmall(big[r], small, smallSize);
      if (idx >= 0 && !seen[idx]) {
        seen[idx] = 1;
        found++;
        if (found == smallSize) break;
      }
    }
    free(seen);
    if (found == smallSize) {
      int len = r - l + 1;
      if (len < bestLen) {
        bestLen = len;
        bestL = l;
        bestR = r;
      }
    }
  }
  if (bestL == -1) {
    *returnSize = 0;
    return NULL;
  }
  int *res = (int *)malloc(sizeof(int) * 2);
  res[0] = bestL;
  res[1] = bestR;
  *returnSize = 2;
  return res;
}

class Solution {
public:
  vector<int> shortestSeq(vector<int> &big, vector<int> &small) {
    unordered_set<int> need(small.begin(), small.end());
    int bestLen = big.size() + 1, bestL = -1, bestR = -1;
    for (int l = 0; l < (int)big.size(); l++) {
      if (!need.count(big[l])) continue;
      int found = 0, r = l;
      unordered_set<int> seen;
      for (; r < (int)big.size(); r++) {
        if (need.count(big[r]) && !seen.count(big[r])) {
          seen.insert(big[r]);
          found++;
          if (found == (int)need.size()) break;
        }
      }
      if (found == (int)need.size()) {
        int len = r - l + 1;
        if (len < bestLen) {
          bestLen = len;
          bestL = l;
          bestR = r;
        }
      }
    }
    if (bestL == -1) return {};
    return {bestL, bestR};
  }
};

func shortestSeq(big []int, small []int) []int {
	need := map[int]bool{}
	for _, x := range small {
		need[x] = true
	}
	bestLen, bestL, bestR := len(big)+1, -1, -1
	for l := 0; l < len(big); l++ {
		if !need[big[l]] {
			continue
		}
		seen := map[int]bool{}
		found, r := 0, l
		for ; r < len(big); r++ {
			if need[big[r]] && !seen[big[r]] {
				seen[big[r]] = true
				found++
				if found == len(need) {
					break
				}
			}
		}
		if found == len(need) {
			if r-l+1 < bestLen {
				bestLen = r - l + 1
				bestL, bestR = l, r
			}
		}
	}
	if bestL == -1 {
		return []int{}
	}
	return []int{bestL, bestR}
}

class Solution {
  public int[] shortestSeq(int[] big, int[] small) {
    Set<Integer> need = new HashSet<>();
    for (int x : small) need.add(x);
    int bestLen = big.length + 1, bestL = -1, bestR = -1;
    for (int l = 0; l < big.length; l++) {
      if (!need.contains(big[l])) continue;
      Set<Integer> seen = new HashSet<>();
      int r = l;
      for (; r < big.length; r++) {
        if (need.contains(big[r]) && !seen.contains(big[r])) {
          seen.add(big[r]);
          if (seen.size() == need.size()) break;
        }
      }
      if (seen.size() == need.size() && r - l + 1 < bestLen) {
        bestLen = r - l + 1;
        bestL = l;
        bestR = r;
      }
    }
    if (bestL == -1) return new int[0];
    return new int[] { bestL, bestR };
  }
}

class Solution:
    def shortestSeq(self, big: List[int], small: List[int]) -> List[int]:
        need = set(small)
        best_len = len(big) + 1
        best = [-1, -1]
        for l in range(len(big)):
            if big[l] not in need:
                continue
            seen = set()
            r = l
            while r < len(big):
                if big[r] in need:
                    seen.add(big[r])
                    if len(seen) == len(need):
                        break
                r += 1
            if len(seen) == len(need) and r - l + 1 < best_len:
                best_len = r - l + 1
                best = [l, r]
        return best if best[0] != -1 else []

impl Solution {
  pub fn shortest_seq(big: Vec<i32>, small: Vec<i32>) -> Vec<i32> {
    let need: HashSet<i32> = small.iter().cloned().collect();
    let mut best_len = big.len() + 1;
    let mut best = vec![-1i32, -1i32];
    for l in 0..big.len() {
      if !need.contains(&big[l]) {
        continue;
      }
      let mut seen: HashSet<i32> = HashSet::new();
      let mut r = l;
      while r < big.len() {
        if need.contains(&big[r]) {
          seen.insert(big[r]);
          if seen.len() == need.len() {
            break;
          }
        }
        r += 1;
      }
      if seen.len() == need.len() && r - l + 1 < best_len {
        best_len = r - l + 1;
        best = vec![l as i32, r as i32];
      }
    }
    if best[0] == -1 {
      vec![]
    } else {
      best
    }
  }
}

const shortestSeq = (big: number[], small: number[]): number[] => {
  const need = new Set(small);
  let bestLen = big.length + 1;
  let best: number[] = [-1, -1];
  for (let l = 0; l < big.length; l++) {
    if (!need.has(big[l])) continue;
    const seen = new Set<number>();
    let r = l;
    while (r < big.length) {
      if (need.has(big[r])) {
        seen.add(big[r]);
        if (seen.size === need.size) break;
      }
      r++;
    }
    if (seen.size === need.size && r - l + 1 < bestLen) {
      bestLen = r - l + 1;
      best = [l, r];
    }
  }
  return best[0] === -1 ? [] : best;
};
